def compute(vars):
    debt_principal = vars["v1"]
    debt_interest = vars["v2"]
    total_obligations = vars["v3"]

    if total_obligations == 0:
        return None

    debt_obligations = debt_principal + debt_interest
    ratio = debt_obligations / total_obligations
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "debt_obligations": debt_obligations,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
